#!/usr/bin/env python3
"""Read only three fixed source edges and one safe config projection."""
import base64,gzip,hashlib,sys,types
sys.dont_write_bytecode=True
raw=gzip.decompress(base64.b64decode('',validate=True))
if hashlib.sha256(raw).hexdigest()!='07a66142e013d9139578b99d9bc39fe1e5704eff66891ca7bb176eb5a21709cf':raise RuntimeError("HOLD_SOURCE_DIGEST")
m=types.ModuleType('three_edge_public_key');m.__file__='<reviewed-three_edge_public_key>';sys.modules[m.__name__]=m
exec(compile(raw,m.__file__,"exec"),m.__dict__)
raw=gzip.decompress(base64.b64decode('',validate=True))
if hashlib.sha256(raw).hexdigest()!='8214b9db42f9d1affb1e86335656af5e751ebc6378d97106b66d5bf1f8c77033':raise RuntimeError("HOLD_SOURCE_DIGEST")
m=types.ModuleType('three_edge_readback');m.__file__='<reviewed-three_edge_readback>';sys.modules[m.__name__]=m
exec(compile(raw,m.__file__,"exec"),m.__dict__)
raise SystemExit(m.entry())
